<template><section class="query-jobs" aria-label="持久只读查询"><h2>持久只读查询</h2><p>BigQuery 与 Hive 查询会保存提交和分页检查点。提交结果未知时先核对；不会以新任务重复执行。结果保留数值原文，不代表已发布资产。</p>
<form @submit.prevent="submit"><label>查询数据源<select v-model="form.datasource_id" required><option value="">请选择当前可读数据源</option><option v-for="v in sources" :key="v.id" :value="v.id">{{v.name}} · {{v.type}}</option></select></label><button v-if="sourceMore" type="button" :disabled="busy" @click="loadSources(true)">更多数据源</button>
<label>只读 SQL<textarea v-model="form.sql" rows="4" required /></label><div class="query-budget"><label>最多结果行<input v-model.number="form.max_rows" type="number" min="1" max="10000" required /></label><label>结果字节上限<input v-model.number="form.max_bytes" type="number" min="1024" max="8388608" required /></label><label>截止秒数<input v-model.number="form.timeout_seconds" type="number" min="1" max="30" required /></label><label v-if="selectedSource?.type==='bigquery'">扫描字节预算<input v-model.number="form.max_scan_bytes" type="number" min="1" max="9007199254740991" required /></label></div><button :disabled="busy||!selectedSource">提交有界查询</button><p v-if="submittedIntent">网络重试会复用相同请求键；更改查询或预算会使用新键。</p></form>
<p v-if="error" role="alert">{{error}}</p><button type="button" :disabled="busy" @click="load(false)">刷新查询列表</button><ul><li v-for="job in jobs" :key="job.id"><button type="button" :disabled="busy" @click="choose(job.id)">{{job.id}} · {{job.status}} · {{job.row_count}} 行</button></li></ul><button v-if="cursor" type="button" :disabled="busy" @click="load(true)">更多查询</button>
<article v-if="current"><h3>查询 {{current.id}}</h3><p>状态：{{current.status}} · 远端：{{current.remote_status||'尚未确认'}} · 清理待确认：{{current.cleanup_pending?'是':'否'}}</p><p v-if="current.error" role="status">{{current.error}}</p><p v-if="current.truncated">达到结果预算，已明确截断。</p><button type="button" :disabled="busy" @click="choose(current.id)">核对查询状态</button><button v-if="!terminal" type="button" :disabled="busy" @click="cancel">请求取消并核对</button><button v-if="current.status==='succeeded'" type="button" :disabled="busy" @click="readResults(false)">读取已保存结果</button><div v-if="results" class="query-table"><table><thead><tr><th v-for="c in results.columns" :key="c">{{c}} · {{results.column_types[c]}}</th></tr></thead><tbody><tr v-for="(row,i) in results.rows" :key="i"><td v-for="c in results.columns" :key="c">{{row[c]===null?'NULL':String(row[c])}}</td></tr></tbody></table></div><button v-if="results?.next_cursor" type="button" :disabled="busy" @click="readResults(true)">下一页结果</button></article>
</section></template>
<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue'
import {useAuthStore} from '@/stores/auth'
import {datasourceApi,type Datasource} from '@/api/datasource'
import {queryJobsApi,type QueryInput,type QueryJob,type QueryResults} from '@/api/datasource/queryJobs'
const auth=useAuthStore(),sources=ref<Datasource[]>([]),sourceMore=ref(false),jobs=ref<QueryJob[]>([]),cursor=ref(''),current=ref<QueryJob>(),results=ref<QueryResults>(),busy=ref(false),error=ref(''),submittedIntent=ref('')
const form=reactive<QueryInput>({datasource_id:'',sql:'',max_rows:100,max_bytes:1048576,timeout_seconds:30,max_scan_bytes:10000000}),selectedSource=computed(()=>sources.value.find(v=>v.id===form.datasource_id)),terminal=computed(()=>current.value&&!current.value.cleanup_pending&&['succeeded','failed','cancelled','timed_out','aborted_unknown'].includes(current.value.status))
let epoch=0,sourcePage=0,requestKey=''
async function perform(fn:(own:number)=>Promise<void>){if(busy.value)return;const own=epoch;busy.value=true;error.value='';try{await fn(own)}catch(e){if(own===epoch)error.value=e instanceof Error?e.message:'查询操作失败'}finally{if(own===epoch)busy.value=false}}
async function loadSources(more=false){const own=epoch;const page=more?sourcePage+1:1;try{const r=await datasourceApi.list({page,page_size:100});if(own!==epoch)return;sources.value=[...(more?sources.value:[]),...(r.data?.items||[]).filter(v=>['hive','bigquery'].includes(v.type))];sourcePage=page;sourceMore.value=page*100<(r.data?.total||0)}catch(e){if(own===epoch)error.value=e instanceof Error?e.message:'数据源读取失败'}}
async function load(more=false){await perform(async own=>{const r=await queryJobsApi.list(more?cursor.value:'');if(own!==epoch)return;jobs.value=more?[...jobs.value,...(r.data?.items||[])]:r.data?.items||[];cursor.value=r.data?.next_cursor||''})}
async function choose(id:string){await perform(async own=>{const r=await queryJobsApi.get(id);if(own!==epoch)return;current.value=r.data;results.value=undefined})}
async function submit(){await perform(async own=>{const input={...form,max_scan_bytes:selectedSource.value?.type==='bigquery'?form.max_scan_bytes:0};const intent=JSON.stringify(input);if(intent!==submittedIntent.value){requestKey=crypto.randomUUID();submittedIntent.value=intent};const r=await queryJobsApi.create(input,requestKey);if(own!==epoch)return;current.value=r.data;results.value=undefined})}
async function cancel(){if(!current.value)return;const id=current.value.id;await perform(async own=>{const r=await queryJobsApi.cancel(id);if(own===epoch)current.value=r.data})}
async function readResults(next:boolean){if(!current.value)return;const id=current.value.id;await perform(async own=>{const r=await queryJobsApi.results(id,next?results.value?.next_cursor:'');if(own===epoch)results.value=r.data})}
function reset(){epoch++;busy.value=false;error.value='';sources.value=[];jobs.value=[];current.value=undefined;results.value=undefined;cursor.value='';sourcePage=0;sourceMore.value=false;submittedIntent.value='';requestKey='';form.datasource_id='';form.sql=''}
watch(()=>`${auth.authEpoch}:${auth.user?.id}:${auth.currentTenant?.id}`,()=>{reset();void loadSources();void load()})
onBeforeUnmount(()=>{epoch++});onMounted(()=>{void loadSources();void load()})
</script>
<style scoped>.query-jobs{padding:24px;margin-top:24px;border:1px solid var(--border-color,#ddd);border-radius:12px}.query-jobs label{display:block;margin:10px 0}.query-jobs input,.query-jobs select,.query-jobs textarea{display:block;max-width:100%;width:100%;padding:8px}.query-jobs button{margin:6px;padding:8px}.query-budget{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:16px}.query-table{overflow:auto}th,td{text-align:left;padding:8px;white-space:nowrap;border-bottom:1px solid #ddd}article{overflow-wrap:anywhere}</style>
